record.field:
# Get active company from context
allowed_company_ids = env.context.get('allowed_company_ids', [])
if allowed_company_ids:
    company_id = allowed_company_ids[0]
    company = env['res.company'].browse(company_id)
else:
    company = env.user.company_id
    company_id = company.id

user = env.user
is_admin = user.has_group('department_vendor_bill_management.group_department_bill_admin')
is_manager = user.has_group('department_vendor_bill_management.group_department_bill_manager')

# Build domain based on role
domain = [
    ('move_type', '=', 'in_invoice'),
    ('is_expense_bill', '=', True),
    ('company_id', '=', company_id)
]

if not is_admin:
    if is_manager:
        employee = env['hr.employee'].sudo().search([
            ('user_id', '=', user.id),
            ('company_id', '=', company_id)
        ], limit=1)

        if employee and employee.department_id:
            dept = employee.department_id
            if dept.company_id:
                if dept.company_id.id == company_id:
                    domain.append(('department_id', '=', dept.id))
                else:
                    domain.append(('create_uid', '=', user.id))
            else:
                domain.append(('department_id', '=', dept.id))
        else:
            domain.append(('create_uid', '=', user.id))
    else:
        domain.append(('create_uid', '=', user.id))

action = {
    'name': 'Expense Bills Dashboard - %s' % company.name,
    'type': 'ir.actions.act_window',
    'res_model': 'account.move',
    'view_mode': 'graph,pivot,list,form',
    'domain': domain,
    'context': {
        'default_company_id': company_id,
        'search_default_group_department': 1,
        'search_default_group_state': 1,
        'graph_measure': 'amount_total',
        'graph_mode': 'bar',
        'graph_groupbys': ['department_id'],
        'allowed_company_ids': [company_id],
    },
}
